bool dhcp_selftest(void)
{
    const unsigned char mac[6]={2,0,0,0,0,1},entropy[10]={0x12,0x34,0x56,0x78};
    struct dhcp_client s={0};unsigned char packet[DHCP_FRAME_BYTES];size_t n=0;
    if (dhcp_client_init(&s,mac,entropy)!=BLOCK_OK || dhcp_encode(&s,false,0,packet,sizeof(packet),&n)!=BLOCK_OK || !dhcp_wire_request_valid(packet,n) || packet[284]!=1) { return false; }
    s.discover_issued=true;dhcp_receive(&s,offer,sizeof(offer));
    if (!s.have_offer || s.offer.address[3]!=10 || s.offer.seconds!=3600 || !s.offer.have_mask || !s.offer.have_router || !s.offer.have_dns) { return false; }
    s.discover_written=true;s.phase=DHCP_REQUESTING;
    if (dhcp_encode(&s,true,0,packet,sizeof(packet),&n)!=BLOCK_OK || !dhcp_wire_request_valid(packet,n) || packet[284]!=3) { return false; }
    dhcp_receive(&s,ack,sizeof(ack));if (s.ack_seen) { return false; }
    s.request_issued=true;dhcp_receive(&s,ack,sizeof(ack));
    return s.ack_seen && s.lease.address[3]==10 && s.lease.server[3]==1 && s.lease.dns[0]==8 && !s.request_written;
}
